def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    result = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue
        sign = '-' if coeff < 0 else '+'
        term = f"{abs(coeff)}" if abs(coeff) != 1 or (i > 0 and i <= n) else ""
        degree = i + 1
        # Format the variable part based on its degree
        if degree > 1:
            term += f"x^{degree}"
        else:
            term += 'x' if degree == 1 else ''
        # Add the term to the result
        result.append(f"{sign}{term}")
    # Combine the terms without spaces
    return ' '.join(result)
```

