def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original) or len(encoded) != len(message):
        return "Failed"

    mapping = {}
    seen_letters = set()

    for i, (e, o) in enumerate(zip(encoded, original)):
        if e != o:
            if e in mapping and mapping[e] != o:
                return "Failed"
            else:
                mapping[e] = o
                seen_letters.add(e)

    # Check if all letters are represented in the mapping
    for c in message:
        if c not in seen_letters:
            return "Failed"

    return "".join(mapping[c] for c in message)
