from typing import Dict

def count_sequences(n: int, last: int, memo: Dict[int, int]) -> int:
    if (n, last) in memo:
        return memo[(n, last)]
    if n == 0 and last == 0:
        return 1
    if n == 0:
        return 0
    memo[(n, last)] = 0
    if last > 0:
        memo[(n, last)] += count_sequences(n, last - n, memo)
        memo[(n, last)] += count_sequences(n, last // 2, memo)

    return memo[(n, last)]
