from collections import *

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    # Initialize a queue for BFS and a set to keep track of visited states
    queue = deque([(A, 0)])
    visited = set([A])

    while queue and queue[0][0] != B:
        cur, steps = queue.popleft()
        for src, tgt in rules:
            if src in cur:
                new_state = cur.replace(src, tgt)
                if new_state not in visited:
                    queue.append((new_state, steps + 1))
                    visited.add(new_state)

    if queue:
        return steps
    else:
        return "NO ANSWER!"
