def next_permutation(perm): 
    k = len(perm) - 2
    while k >= 0:
        if perm[k] < perm[k + 1]:
            break
        k -= 1
    if k < 0:
        return False 

    j = len(perm) - 1
    while perm[j] < perm[k]:
        j -= 1

    perm[k], perm[j] = perm[j], perm[k] 

    perm[k + 1:] = list(reversed(perm[k + 1:])) 

    return True
